2. Задайте токен бота из файла `.env`:

```javascript
const { TOKEN } = process.env;
```

3. Настройте обработчик для события `ready` и запустите бота:

```javascript
client.on('ready', () => {
  console.log(`Logged in as ${client.user.tag}`);
});

client.login(TOKEN);
```

4. Добавьте слэш-команду бан, которая будет блокировать пользователя в канале, где была вызвана команда:

```javascript
const { SlashCommandBuilder } = require('discord.js');

client.on('interactionCreate', async interaction => {
  if (!interaction.isCommand()) return;

  if (interaction.commandName === 'ban') {
    if (!interaction.member.permissions.has('BAN_MEMBERS')) {
      return interaction.reply({
        content: 'У вас нет прав на банов.',
        ephemeral: true,
      });
    }

    if (!interaction.guild.members.me.permissions.has('BAN_MEMBERS')) {
      return interaction.reply({
        content: 'Я не имею прав на банов в этом сервере.',
        ephemeral: true,
      });
    }

    const member = interaction.options.getMember('user');
    if (!member) {
      return interaction.reply({
        content: 'Пользователь не найден.',
        ephemeral: true,
      });
    }

    if (member.permissionsIn(interaction.channel).has('SEND_MESSAGES')) {
      return interaction.reply({
        content: 'Невозможно заблокировать этого пользователя в данном канале.',
        ephemeral: true,
      });
    }

    try {
      await interaction.guild.bans.create(member, {
        reason: `Banned by ${interaction.user.tag}`,
      });
      interaction.reply({ content: `${member.user.tag} был заблокирован.` });
    } catch (error) {
      console.error(error);
      interaction.reply({
        content: 'Ошибка при попытке заблокировать пользователя.',
        ephemeral: true,
      });
    }
  }
});

const data = new SlashCommandBuilder()
  .setName('ban')
  .setDescription('Блокирует пользователя в канале.')
  .addUserOption(option =>
    option
      .setName('user')
      .setDescription('Пользователь, которого вы хотите заблокировать.')
      .setRequired(true),
  );

client.on('ready', () => {
  client.application.commands.create({
    commandData: data,
    guild: client.guilds.cache.first(),
  });
});
```

5. Запустите сервер Node.js, чтобы запустить бота:

```bash
node index.js
``` 

