    // Convert opening angle brackets (<) to their HTML entity (&lt;)
    size_t pos = 0;
    while ((pos = text.find('<', pos)) != std::string::npos) {
        html_formatted_text += text.substr(pos, 1);
        html_formatted_text += "&lt;";
        pos += 1;
    }

    // Convert closing angle brackets (>) to their HTML entity (&gt;)
    pos = 0;
    while ((pos = text.find('>', pos)) != std::string::npos) {
        html_formatted_text += text.substr(pos, 1);
        html_formatted_text += "&gt;";
        pos += 1;
    }

    // Convert ampersands (&) to their HTML entity (&amp;)
    pos = 0;
    while ((pos = text.find('&', pos)) != std::string::npos) {
        html_formatted_text += text.substr(pos, 1);
        html_formatted_text += "&amp;";
        pos += 1;
    }

    return html_formatted_text;
}
```

This function takes a `const std::string&` as input and returns a `std::string`. It works by iterating through the input string and replacing occurrences of `<`, `>`, and `&` characters with their corresponding HTML entities.

